if (in_array($driverName, ['mysql', 'mariadb'], true)
    && preg_match('/^(?<field>[A-Za-z_][A-Za-z0-9_.]*) ->> (?<path>.+)$/x', $column, $matches)) {
    // 仅改写纯列名 + 路径的形态
}
```
